//! Fork: the stored shared context import (specs/fork-rust-imported-history.md, Shared context) against rows Node
//! wrote (`fixtures/shared_context_golden.json`, regenerated by `fixtures/gen-shared-context-import.mts`).
use rust_cli_kernel_api::ids::SessionId;
use rust_cli_kernel_api::store::{
    SessionStore, SharedContextImport, SharedContextTransition, StoreError, StoreQueries,
};
use serde_json::Value;

use crate::tests::{TestStore, started};

fn golden() -> Value {
    serde_json::from_str(include_str!("fixtures/shared_context_golden.json")).unwrap()
}

/// The import as the protocol hands it over: the schema's output (`parsed` in the golden).
fn import_of(parsed: &Value) -> SharedContextImport {
    SharedContextImport {
        title: parsed["title"].as_str().unwrap().to_owned(),
        created_at: parsed["createdAt"].as_u64(),
        markdown: parsed["markdown"].as_str().unwrap().to_owned(),
        provenance: parsed["provenance"]
            .as_object()
            .cloned()
            .unwrap_or_default(),
    }
}

fn transition(expected: &[&str], status: &str, source: Option<&str>) -> SharedContextTransition {
    SharedContextTransition {
        context_id: "ctx-1".to_owned(),
        expected: expected.iter().map(|s| (*s).to_owned()).collect(),
        status: status.to_owned(),
        source_id: source.map(str::to_owned),
    }
}

fn session_row(t: &TestStore, id: &str) -> Vec<Vec<Value>> {
    t.rows(&format!(
        "select title, title_source, slug, time_created, time_title_updated, permission from session where id = '{id}'"
    ))
}

fn golden_session(case: &Value) -> Vec<Vec<Value>> {
    let node = &case["session"];
    vec![vec![
        node["title"].clone(),
        node["title_source"].clone(),
        node["slug"].clone(),
        node["time_created"].clone(),
        node["time_title_updated"].clone(),
        node["permission"].clone(),
    ]]
}

fn entry_data(t: &TestStore) -> Value {
    t.rows("select data from session_entry where type = 'v4/shared_context_import'")[0][0].clone()
}

fn message_data(t: &TestStore, id: &str) -> Value {
    t.rows(&format!("select data from message where id = '{id}'"))[0][0].clone()
}

/// The rows the import writes are the rows Node wrote for the same input: `data` byte for byte.
#[tokio::test]
async fn the_rows_equal_the_ones_node_wrote() {
    let golden = golden();
    let t = TestStore::new();
    started(&t, "sess_ctx1").await;
    t.store
        .import_shared_context(&SessionId::new("sess_ctx1"), &import_of(&golden["history"]))
        .await
        .unwrap();

    assert_eq!(session_row(&t, "sess_ctx1"), golden_session(&golden));
    let messages = t
        .rows("select id, time_created, time_updated, data from message order by time_created, id");
    let expected: Vec<Vec<Value>> = golden["messages"]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| {
            ["id", "time_created", "time_updated", "data"]
                .map(|key| row[key].clone())
                .to_vec()
        })
        .collect();
    assert_eq!(messages, expected);
    let parts =
        t.rows("select id, message_id, time_created, data from part order by time_created, id");
    let expected: Vec<Vec<Value>> = golden["parts"]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| {
            ["id", "message_id", "time_created", "data"]
                .map(|key| row[key].clone())
                .to_vec()
        })
        .collect();
    assert_eq!(parts, expected);
    let entries = t.rows(
        "select id, session_id, type, time_created, time_updated, data from session_entry where type = 'v4/shared_context_import' order by id",
    );
    let expected: Vec<Vec<Value>> = golden["entries"]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| {
            [
                "id",
                "session_id",
                "type",
                "time_created",
                "time_updated",
                "data",
            ]
            .map(|key| row[key].clone())
            .to_vec()
        })
        .collect();
    assert_eq!(entries, expected);
}

/// No `contextId`, `status`, `shareUrl` or `createdAt`: the defaults land at the end of the entry's `data`, as in
/// Node, and the title the schema trimmed is the session's.
#[tokio::test]
async fn the_defaults_and_key_order_equal_the_ones_node_wrote() {
    let golden = golden();
    let minimal = &golden["minimal"];
    let t = TestStore::new();
    started(&t, "sess_ctx2").await;
    t.source.at(5000);
    t.store
        .import_shared_context(&SessionId::new("sess_ctx2"), &import_of(&minimal["parsed"]))
        .await
        .unwrap();
    assert_eq!(session_row(&t, "sess_ctx2"), golden_session(minimal));
    assert_eq!(
        entry_data(&t),
        minimal["entries"][0]["data"],
        "the entry data"
    );
    let part = t.rows("select data from part")[0][0].clone();
    assert_eq!(part, minimal["parts"][0]["data"]);
    // The session has a model here, Node's golden session had none: compare without the model members.
    let data: Value = serde_json::from_str(
        message_data(&t, "msg_sess_ctx2_shared_context")
            .as_str()
            .unwrap(),
    )
    .unwrap();
    let node: Value =
        serde_json::from_str(minimal["messages"][0]["data"].as_str().unwrap()).unwrap();
    let strip = |mut value: Value| {
        value.as_object_mut().unwrap().remove("model");
        value.as_object_mut().unwrap().remove("modelSelection");
        value
    };
    assert_eq!(strip(data), strip(node));
}

/// Node's `transitionSharedContextImport` steps: the entry and the context message after each.
#[tokio::test]
async fn the_transitions_equal_the_ones_node_wrote() {
    let golden = golden();
    let steps = &golden["steps"];
    let t = TestStore::new();
    started(&t, "sess_ctx1").await;
    let id = SessionId::new("sess_ctx1");
    t.store
        .import_shared_context(&id, &import_of(&golden["history"]))
        .await
        .unwrap();
    let message = "msg_sess_ctx1_shared_context";
    let check = |name: &str| {
        assert_eq!(entry_data(&t), steps[name]["entry"], "{name}: entry");
        assert_eq!(
            message_data(&t, message),
            steps[name]["message"],
            "{name}: message"
        );
    };
    let ok = t
        .store
        .transition_shared_context(&id, &transition(&["pending"], "reserved", Some("queue_q1")))
        .await
        .unwrap();
    assert_eq!(ok, steps["reserve"]["ok"]);
    check("reserve");
    let ok = t
        .store
        .transition_shared_context(&id, &transition(&["pending"], "reserved", Some("queue_q2")))
        .await
        .unwrap();
    assert_eq!(ok, steps["reserve_again"]["ok"]);
    check("reserve_again");
    let ok = t
        .store
        .transition_shared_context(&id, &transition(&["reserved"], "pending", Some("queue_q1")))
        .await
        .unwrap();
    assert_eq!(ok, steps["revert"]["ok"]);
    check("revert");
}

/// The discard path, a repeated discard, and importing the same share again (Node returns the stored session).
#[tokio::test]
async fn a_discarded_context_stays_discarded() {
    let golden = golden();
    let steps = &golden["steps"];
    let t = TestStore::new();
    started(&t, "sess_ctx1").await;
    let id = SessionId::new("sess_ctx1");
    let import = import_of(&golden["history"]);
    t.store.import_shared_context(&id, &import).await.unwrap();
    assert!(
        t.store
            .transition_shared_context(&id, &transition(&["pending"], "discarded", None))
            .await
            .unwrap()
    );
    assert_eq!(entry_data(&t), steps["discard"]["entry"]);
    assert_eq!(
        message_data(&t, "msg_sess_ctx1_shared_context"),
        steps["discard"]["message"]
    );
    assert!(
        !t.store
            .transition_shared_context(&id, &transition(&["pending"], "discarded", None))
            .await
            .unwrap()
    );
    t.store.import_shared_context(&id, &import).await.unwrap();
    assert_eq!(entry_data(&t), steps["recommit"]["entry"]);
    assert_eq!(
        message_data(&t, "msg_sess_ctx1_shared_context"),
        steps["recommit"]["message"]
    );
}

/// A transition names a context that is not there: nothing changes.
#[tokio::test]
async fn an_unknown_context_is_not_transitioned() {
    let golden = golden();
    let t = TestStore::new();
    started(&t, "sess_ctx1").await;
    let id = SessionId::new("sess_ctx1");
    t.store
        .import_shared_context(&id, &import_of(&golden["history"]))
        .await
        .unwrap();
    let mut other = transition(&["pending"], "reserved", None);
    other.context_id = "nope".to_owned();
    assert!(
        !t.store
            .transition_shared_context(&id, &other)
            .await
            .unwrap()
    );
    assert_eq!(entry_data(&t), golden["entries"][0]["data"]);
}

#[tokio::test]
async fn an_unknown_session_is_not_found() {
    let golden = golden();
    let t = TestStore::new();
    let error = t
        .store
        .import_shared_context(&SessionId::new("sess_none"), &import_of(&golden["history"]))
        .await
        .unwrap_err();
    assert!(matches!(error, StoreError::NotFound { .. }), "{error:?}");
}

/// A pending context is a candidate: the model history of the session does not have it.
#[tokio::test]
async fn a_pending_context_is_not_loaded() {
    let golden = golden();
    let t = TestStore::new();
    started(&t, "sess_ctx1").await;
    let id = SessionId::new("sess_ctx1");
    t.store
        .import_shared_context(&id, &import_of(&golden["history"]))
        .await
        .unwrap();
    let loaded = t.store.load(&id).await.unwrap();
    assert_eq!(loaded.meta.title, "Shared chat");
    assert!(loaded.messages.is_empty(), "{:?}", loaded.messages);
}
